{
  "html": "<div data-ui-unit="E4a" class="e4a-card">
  <button class="e4a-fav-btn" disabled aria-label="김서연 찜한 상태 예시">
    <img src="assets/reference/heart.svg" alt="찜하기" class="e4a-fav-icon">
  </button>
  <div class="e4a-header">
    <img src="assets/reference/avatar-1.png" alt="김서연 프로필" class="e4a-avatar">
    <div class="e4a-text-col">
      <span class="e4a-name">김서연</span>
      <div class="e4a-meta">
        <img src="assets/reference/bookmark-check.svg" alt="" class="e4a-badge-icon">
        <span class="e4a-badge">현직</span>
        <span class="e4a-divider"></span>
        <span class="e4a-company">스타트업 A</span>
      </div>
    </div>
  </div>
  <p class="e4a-desc">프로덕트 전략 및 UX 리딩 담당으로, B2B SaaS 서비스의 0→1 과정을 주도했습니다.</p>
</div>",
  "css": ".e4a-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.e4a-fav-btn {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  background: transparent;
  cursor: default;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
}

.e4a-fav-icon {
  width: 24px;
  height: 24px;
  object-fit: contain;
}

/* Fallback fill for the heart icon if SVG doesn't support it */
.e4a-card .e4a-fav-icon[alt="찜하기"] {
  fill: #e85260;
}

.e4a-header {
  display: flex;
  align-items: flex-start;
  margin-top: 4px; /* Account for absolute button */
  min-width: 0;
}

.e4a-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}

.e4a-text-col {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-left: 8px;
  min-width: 0;
  width: 100%;
}

.e4a-name {
  font-size: 18px;
  line-height: 24px;
  font-weight: 700;
  color: #283548;
  white-space: nowrap;
}

.e4a-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.e4a-badge-icon {
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  fill: #365bcc;
}

.e4a-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 20px;
  padding: 1px 6px;
  border-radius: 6px;
  background-color: #eef2fb; /* Pale blue */
  color: #365bcc;
  font-size: 12px;
  line-height: 20px;
  white-space: nowrap;
}

.e4a-divider {
  width: 1px;
  height: 12px;
  background-color: #dfe3e8;
  flex-shrink: 0;
  margin: 0 2px;
}

.e4a-company {
  font-size: 14px;
  line-height: 20px;
  color: #566273;
  white-space: nowrap;
}

.e4a-desc {
  margin-top: 8px;
  font-size: 14px;
  line-height: 1.57;
  color: #566273;
  min-width: 0;
}

@media (min-width: 320px) {
  .e4a-name {
    font-size: 18px;
  }
  .e4a-company {
    font-size: 14px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .e4a-card * {
    transition: none;
  }
}"
}
